    Parameters
    ----------
    specs: dict
        a dict with keys value and name
    name: str
        the spec name
    Return
    ------
    value: float or None
        value of the spec if exists, None otherwise
    """
def get_value(specs: Any, name: Any) -> object {
    value = None;
    for s in specs {
        if (s['name'] == name) {
            value = s['value'];
            break;
        }
    }
    return value;
}

